ALTER TABLE users ADD COLUMN invitation_pending BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE sessions ADD COLUMN mfa_verified BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE account_tokens (token_hash CHAR(64) PRIMARY KEY, user_id INT NOT NULL, purpose ENUM('invite','reset') NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(user_id,purpose));
CREATE TABLE admin_mfa (user_id INT PRIMARY KEY, secret TEXT NULL, pending_secret TEXT NULL, pending_until DATETIME NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, last_counter BIGINT NOT NULL DEFAULT -1, recovery_hashes JSON NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE tenant_documents (id INT PRIMARY KEY AUTO_INCREMENT, tenancy_id INT NOT NULL, title VARCHAR(200) NOT NULL, filename VARCHAR(80) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE tenant_notices (id INT PRIMARY KEY AUTO_INCREMENT, tenancy_id INT NOT NULL, title VARCHAR(200) NOT NULL, content TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE maintenance_tickets (id INT PRIMARY KEY AUTO_INCREMENT, tenancy_id INT NOT NULL, subject VARCHAR(200) NOT NULL, description TEXT NOT NULL, status ENUM('new','in-progress','resolved') NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(tenancy_id) REFERENCES tenancies(id));
CREATE TABLE maintenance_messages (id INT PRIMARY KEY AUTO_INCREMENT, ticket_id INT NOT NULL, author_id INT NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(ticket_id) REFERENCES maintenance_tickets(id) ON DELETE CASCADE, FOREIGN KEY(author_id) REFERENCES users(id));
